/* A latitude/longitude source image must be reprojected per Mercator row, not stretched as an imageOverlay. */
export class EnvironmentalMapLayer{
  constructor(L,map,repository){this.L=L;this.map=map;this.repository=repository;this.layer=null;this.vectors=null;this.generation=0;this.images=new Map();this.opacity=.8;}
  setOpacity(value){if(!Number.isFinite(value)||value<0||value>1)throw Error('invalid_opacity');this.opacity=value;this.layer?.setOpacity(value);if(this.vectors?.canvas)this.vectors.canvas.style.opacity=String(value);}
  clear(){++this.generation;if(this.layer)this.map.removeLayer(this.layer);if(this.vectors)this.map.removeLayer(this.vectors);this.layer=null;this.vectors=null;}
  async show(datasetId,variable,timeId,{showVectors=true}={}){
    this.clear();const generation=this.generation,manifest=await this.repository.manifest(datasetId),url=await this.repository.overviewUrl(datasetId,variable,timeId);
    if(!this.images.has(url)){const image=new Image();image.decoding='async';const promise=new Promise((resolve,reject)=>{image.onload=()=>resolve(image);image.onerror=()=>{this.images.delete(url);reject(Error('environmental_image_unavailable'));};});image.src=url;this.images.set(url,promise);if(this.images.size>4)this.images.delete(this.images.keys().next().value);}
    const image=await this.images.get(url);if(generation!==this.generation)return {status:'superseded'};
    const bbox=manifest.overview.bbox||[-180,-90,180,90];
    const Layer=this.L.GridLayer.extend({createTile(coords,done){const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;const count=2**coords.z,x=((coords.x%count)+count)%count,west=x/count*360-180,east=(x+1)/count*360-180,left=Math.max(west,bbox[0]),right=Math.min(east,bbox[2]);
      if(left<right){const sx=(left-bbox[0])/(bbox[2]-bbox[0])*image.width,sw=(right-left)/(bbox[2]-bbox[0])*image.width,dx=(left-west)/(east-west)*256,dw=(right-left)/(east-west)*256;
      for(let row=0;row<256;row++){const normalizedY=(coords.y*256+row+.5)/(256*count),lat=Math.atan(Math.sinh(Math.PI*(1-2*normalizedY)))*180/Math.PI;if(lat<bbox[1]||lat>bbox[3])continue;const sy=Math.max(0,Math.min(image.height-1,Math.floor((bbox[3]-lat)/(bbox[3]-bbox[1])*image.height)));ctx.drawImage(image,sx,sy,sw,1,dx,row,dw,1);}}
      queueMicrotask(()=>done(null,canvas));return canvas;}});
    this.layer=new Layer({opacity:this.opacity,tileSize:256,attribution:manifest.displayAttribution||'DMI / C3S · source-period mean SST',className:'environmental-raster-layer',keepBuffer:1}).addTo(this.map);
    if(manifest.vectors&&showVectors){const points=await this.repository.vectorField(datasetId,timeId);if(generation!==this.generation)return {status:'superseded'};const L=this.L,VectorLayer=L.Layer.extend({onAdd(map){this.map=map;this.canvas=L.DomUtil.create('canvas','environmental-vector-layer');this.canvas.style.pointerEvents='none';map.getPanes().overlayPane.append(this.canvas);map.on('moveend zoomend resize',this.draw,this);this.draw();},onRemove(map){map.off('moveend zoomend resize',this.draw,this);this.canvas.remove();},draw(){const map=this.map,canvas=this.canvas,size=map.getSize(),ratio=Math.min(devicePixelRatio||1,2);canvas.width=size.x*ratio;canvas.height=size.y*ratio;canvas.style.width=size.x+'px';canvas.style.height=size.y+'px';L.DomUtil.setPosition(canvas,map.containerPointToLayerPoint([0,0]));const c=canvas.getContext('2d');c.scale(ratio,ratio);c.strokeStyle='#153e4dcc';c.lineWidth=1.15;c.lineCap='round';const occupied=new Set();let drawn=0;for(const p of points){const q=map.latLngToContainerPoint([p.latitude,p.longitude]);if(q.x<0||q.y<0||q.x>size.x||q.y>size.y)continue;const key=Math.floor(q.x/25)+':'+Math.floor(q.y/25);if(occupied.has(key))continue;occupied.add(key);const speed=Math.hypot(p.u,p.v);if(speed<.005)continue;const dx=p.u/speed,dy=-p.v/speed,len=11+Math.min(7,speed*5),ax=q.x-dx*len/2,ay=q.y-dy*len/2,bx=q.x+dx*len/2,by=q.y+dy*len/2;c.beginPath();c.moveTo(ax,ay);c.lineTo(bx,by);c.moveTo(bx-dx*4-dy*3,by-dy*4+dx*3);c.lineTo(bx,by);c.lineTo(bx-dx*4+dy*3,by-dy*4-dx*3);c.stroke();drawn++;}canvas.dataset.arrowCount=drawn;}});this.vectors=new VectorLayer().addTo(this.map);}
    return {status:'displayed',resolutionDegrees:manifest.overview.stepDegrees,pointResolutionDegrees:manifest.grid.nominalStepDegrees,method:'source-cell display with Mercator reprojection'};
  }
}
